#include <iostream>
#include <vector>


int binary_search(const std::vector<int>& v, int x) {

    int l = 0, r = (int)v.size();                      
    while (r - l > 1) {
        int m = (l + r) / 2;
        if (v[m] <= x) l = m;
        else r = m;
    }
    return (!v.empty() && v[l] == x) ? l + 1 : -1;
}

